create or replace function public.player_equipment_sell(p_channel text,p_item_id text,p_request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=(select auth.uid());item private.player_equipment_items;profile private.player_equipment_profiles;wallet private.player_resource_wallets;
begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test') or p_request_id is null then raise exception '出售資料不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id) then raise exception '重複的出售請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-equipment-'||p_channel));select * into item from private.player_equipment_items where user_id=uid and channel=p_channel and item_id=p_item_id for update;if item.item_id is null then raise exception '找不到此裝備';end if;if item.equipped then raise exception '請先卸下裝備';end if;select * into wallet from private.player_resource_wallets where user_id=uid and channel=p_channel for update;if wallet.user_id is null then raise exception '伺服器資源帳本尚未建立';end if;delete from private.player_equipment_items where user_id=uid and channel=p_channel and item_id=p_item_id;update private.player_resource_wallets set spirit_stone=spirit_stone+1,revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into wallet;update private.player_equipment_profiles set revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into profile;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload) values(uid,p_channel,profile.revision,'equipment_sold',p_request_id,jsonb_build_object('itemId',p_item_id,'earned',1));return jsonb_build_object('equipment',private.equipment_snapshot(uid,p_channel),'wallet',private.wallet_snapshot(wallet),'earned',1);end $$;
revoke execute on function public.player_equipment_sell(text,text,uuid) from public,anon;
grant execute on function public.player_equipment_sell(text,text,uuid) to authenticated;
